D = '/tmp/fabro'
print(sorted(os.listdir(D)))
for name in ('spec.md', 'review-brief.md', 'last-review.md', 'review-notes.md', 'security-review.md', 'todo.md'):
    if os.path.exists(D + '/' + name):
        print('=====', name)
        print(open(D + '/' + name).read()[:7000])
"
    ]

    // ------------------------------------------------------------------
    // Edges. Keep the conditions: with plain edges a failed step does NOT
    // stop the run. Where a script picks the route, the edge without a
    // route in its condition is the safe default (the security reviewer,
    // or a human).
    // ------------------------------------------------------------------
    start -> check_issue
    check_issue -> install [condition="outcome=succeeded"]
    check_issue -> exit    [label="Refused"]
    install -> spec        [condition="outcome=succeeded"]
    install -> release     [label="Install failed"]

    spec -> save_spec
    save_spec -> approve   [condition="outcome=succeeded"]
    save_spec -> spec      [label="Spec incomplete", condition="outcome=failed && context.command.output contains ROUTE_spec"]
    save_spec -> release   [label="No usable spec"]
    approve -> implement   [label="[A] Approve"]
    approve -> spec        [label="Revise", freeform=true]
    approve -> release     [label="[X] Reject"]

    implement -> verify
    deep_fix  -> verify

    verify -> review          [label="Standard review", weight=10, condition="outcome=succeeded && context.command.output contains ROUTE_standard"]
    verify -> security_review [label="Security review", condition="outcome=succeeded"]
    verify -> implement       [label="Fix", condition="outcome=failed && context.command.output contains ROUTE_implement"]
    verify -> deep_fix        [label="Escalate", condition="outcome=failed && context.command.output contains ROUTE_deep"]
    verify -> stuck           [label="Out of attempts"]

    review          -> review_gate
    security_review -> review_gate

    review_gate -> release         [label="Approved", condition="outcome=succeeded"]
    review_gate -> verify          [label="Repo changed", condition="outcome=failed && context.command.output contains ROUTE_reverify"]
    review_gate -> security_review [label="Hand over to security review", condition="outcome=failed && context.command.output contains ROUTE_security"]
    review_gate -> implement       [label="Fix findings", condition="outcome=failed && context.command.output contains ROUTE_implement"]
    review_gate -> deep_fix        [label="Fix findings (escalated)", condition="outcome=failed && context.command.output contains ROUTE_deep"]
    review_gate -> stuck           [label="Needs a human"]

    stuck -> release  [label="[X] Stop, fail the run"]
    release -> exit
    stuck -> deep_fix [label="[S] One more attempt, strong model"]
}

