+  --crit: #b42318;
+  --high: #d97706;
+  --med: #a16207;
+  --low: #2563eb;
+  --info: #64748b;
+  --ok: #15803d;
+  --bad: #b91c1c;
+  --warn: #b45309;
+}
+
+@media (prefers-color-scheme: dark) {
+  :root {
+    --bg: #0f172a;
+    --panel: #111827;
+    --panel-strong: #172036;
+    --fg: #e5ecff;
+    --muted: #9eabc8;
+    --line: #22304f;
+    --accent: #7ea0ff;
+    --accent-strong: #9bb5ff;
+    --code: #02061799;
+    --shadow: 0 22px 40px -30px rgba(2, 6, 23, 0.9);
+  }
+}
+
+* { box-sizing: border-box; }
+html { background: var(--bg); }
+body {
+  margin: 0;
+  background: linear-gradient(180deg, var(--panel-strong) 0, var(--bg) 200px);
+  color: var(--fg);
+  font: 14px/1.6 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+}
+a { color: var(--accent); text-decoration-thickness: 1.5px; text-underline-offset: 2px; }
+a:hover { color: var(--accent-strong); }
+a:focus-visible,
+button:focus-visible,
+input:focus-visible,
+select:focus-visible,
+textarea:focus-visible,
+summary:focus-visible {
+  outline: 2px solid var(--accent);
+  outline-offset: 2px;
+}
+code, pre {
+  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
+  font-size: 12.5px;
+}
+pre {
+  margin: 0;
+  padding: 0.85rem 1rem;
+  border: 1px solid var(--line);
+  border-radius: 14px;
+  background: var(--code);
+  overflow-x: auto;
+  white-space: pre-wrap;
+}
+code {
+  overflow-wrap: anywhere;
+}
+h1, h2, h3, p, ul, ol { margin-top: 0; }
+h1 { margin-bottom: 0.5rem; font-size: clamp(1.9rem, 3vw, 2.5rem); line-height: 1.15; }
+h2 { margin-bottom: 0.8rem; font-size: 1.1rem; }
+h3 { margin-bottom: 0.7rem; font-size: 1rem; }
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 10;
+  backdrop-filter: blur(14px);
