+  border-bottom: 1px solid var(--line);
+}
+.site-header__inner {
+  max-width: 1280px;
+  margin: 0 auto;
+  padding: 0.9rem 1.25rem;
+  display: flex;
+  align-items: center;
+  gap: 1rem;
+}
+.brand {
+  font-weight: 800;
+  letter-spacing: 0.04em;
+  color: var(--fg);
+  text-decoration: none;
+}
+.site-nav {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 0.35rem;
+}
+.site-nav a {
+  color: var(--muted);
+  text-decoration: none;
+  padding: 0.45rem 0.8rem;
+  border-radius: 999px;
+}
+.site-nav a:hover,
+.site-nav a:focus-visible {
+  color: var(--fg);
+  background: var(--panel-strong);
+}
+.user {
+  margin-left: auto;
+  color: var(--muted);
+  font-size: 0.9rem;
+  overflow-wrap: anywhere;
+}
+.page-shell {
+  max-width: 1280px;
+  margin: 0 auto;
+  padding: 1.5rem 1.25rem 3rem;
+}
+.page { display: grid; gap: 1rem; }
+.page-header {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: end;
+  justify-content: space-between;
+  gap: 1rem;
+}
+.eyebrow {
+  margin-bottom: 0.45rem;
+  color: var(--muted);
+  font-size: 0.82rem;
+  font-weight: 700;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+}
+.lead, .prose {
+  color: var(--muted);
+  white-space: pre-wrap;
+  overflow-wrap: anywhere;
+}
+.stack { display: grid; gap: 1rem; align-content: start; }
+.layout-two-col {
+  display: grid;
+  grid-template-columns: minmax(0, 2fr) minmax(280px, 1fr);
+  gap: 1rem;
+  align-items: start;
+}
+.card {
+  min-width: 0;
+  padding: 1.1rem;
+  border: 1px solid var(--line);
+  border-radius: 20px;
+  background: var(--panel);
+  box-shadow: var(--shadow);
+}
+.section-heading {
+  display: flex;
+  justify-content: space-between;
+  align-items: start;
+  gap: 0.75rem;
+  margin-bottom: 0.9rem;
+}
+.section-heading h2,
+.section-heading p {
+  margin-bottom: 0;
+}
+.badge-row {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 0.45rem;
+  margin: 0.75rem 0;
+}
+.badge {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.25rem;
+  padding: 0.2rem 0.7rem;
+  border: 1px solid currentColor;
+  border-radius: 999px;
+  font-size: 0.78rem;
+  font-weight: 700;
+  text-transform: lowercase;
+  white-space: nowrap;
+}
+.muted { color: var(--muted); }
+.saved { color: var(--ok); font-size: 0.84rem; }
+.err { color: var(--bad); }
+.sev-critical { color: var(--crit); }
+.sev-high { color: var(--high); }
+.sev-medium { color: var(--med); }
+.sev-low { color: var(--low); }
+.sev-info { color: var(--info); }
+.dyn-reproduced, .st-done, .st-ok, .tr-tp { color: var(--ok); }
+.st-failed, .st-harness_error, .st-output_invalid, .st-timeout, .st-budget_exceeded, .tr-fp { color: var(--bad); }
+.st-running, .st-queued, .tr-accepted, .dyn-inconclusive { color: var(--warn); }
+.st-skipped, .st-superseded, .st-stale, .tr-new { color: var(--muted); }
+.lb-reproduced { color: var(--crit); }
+.lb-likely { color: var(--high); }
+.lb-inconclusive { color: var(--muted); }
+.filters {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
+  gap: 0.9rem;
+  align-items: end;
+}
+.filters > button {
+  justify-self: start;
+  min-width: 10rem;
+}
+label,
+legend {
+  display: block;
+  color: var(--muted);
+  font-size: 0.82rem;
+  font-weight: 600;
+}
+input,
+select,
+textarea,
+button {
+  width: 100%;
+  margin-top: 0.35rem;
+  padding: 0.7rem 0.8rem;
+  color: var(--fg);
+  background: var(--panel);
+  border: 1px solid var(--line);
+  border-radius: 12px;
+  font: inherit;
+}
+textarea { min-height: 8rem; resize: vertical; }
+button {
+  width: auto;
+  border-color: var(--accent);
+  background: var(--accent);
+  color: #fff;
+  font-weight: 700;
+  cursor: pointer;
+}
+button:hover { background: var(--accent-strong); }
+.choice-group {
+  margin: 0 0 1rem;
+  padding: 0;
+  border: 0;
+  display: grid;
+  gap: 0.55rem;
+}
+.choice-group label {
+  display: flex;
+  align-items: center;
+  gap: 0.55rem;
+  color: var(--fg);
+}
+.choice-group input { width: auto; margin: 0; }
+.kv {
+  margin: 0;
+  display: grid;
+  grid-template-columns: minmax(120px, max-content) minmax(0, 1fr);
+  gap: 0.45rem 1rem;
+}
+.kv dt {
+  color: var(--muted);
+  font-weight: 600;
+}
+.kv dd {
+  margin: 0;
+  overflow-wrap: anywhere;
+}
+.flow {
+  margin: 0;
+  padding: 0;
+  list-style: none;
+  display: grid;
+  gap: 0.9rem;
+}
+.flow li {
+  padding-left: 1rem;
+  border-left: 3px solid var(--line);
+}
+.flow li.source { border-left-color: var(--accent); }
+.flow li.sink { border-left-color: var(--high); }
+.empty-state {
+  padding: 1rem;
+  border: 1px dashed var(--line);
+  border-radius: 16px;
+  background: var(--panel-strong);
+}
+.table-wrap {
+  width: 100%;
+  overflow-x: auto;
+}
+.data-table {
+  width: 100%;
+  min-width: 640px;
+  border-collapse: separate;
+  border-spacing: 0;
+}
+.data-table th,
+.data-table td {
+  padding: 0.8rem 0.9rem;
+  vertical-align: top;
+  border-bottom: 1px solid var(--line);
+  text-align: left;
+}
+.data-table th {
+  position: sticky;
+  top: 0;
+  background: var(--panel);
+  color: var(--muted);
+  font-size: 0.77rem;
+  text-transform: uppercase;
+  letter-spacing: 0.04em;
+}
+.data-table tr:last-child td { border-bottom: 0; }
+.num { text-align: right; font-variant-numeric: tabular-nums; }
+.pager {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 0.9rem;
+  margin-top: 1rem;
+}
+.results-region { display: contents; }
+.detail-small { font-size: 0.78rem; }
+.tl ol {
+  margin: 0;
+  padding: 0;
+  list-style: none;
+}
+.tl-ev,
+.tl-group {
+  margin-bottom: 0.7rem;
+  padding-left: 0.85rem;
+  border-left: 3px solid var(--line);
+}
+.tl-ev {
+  display: grid;
+  grid-template-columns: 70px 140px 180px minmax(0, 1fr);
+  gap: 0.25rem 0.8rem;
+  align-items: start;
+}
+.tl time {
+  color: var(--muted);
+  font-variant-numeric: tabular-nums;
+  font-size: 0.78rem;
+}
+.tl-kind {
+  font-size: 0.82rem;
+  font-weight: 700;
+}
+.tl-where,
+.tl-msg,
+.tl-data code { overflow-wrap: anywhere; }
+.tl-where {
+  color: var(--muted);
+  font-size: 0.78rem;
+}
+.tl-msg { white-space: pre-wrap; }
+.tl-data {
+  grid-column: 4;
+  font-size: 0.82rem;
+  margin-top: 0.2rem;
+}
+.tl-data .kv {
+  grid-template-columns: minmax(80px, max-content) minmax(0, 1fr);
+}
+.tl-group summary {
+  cursor: pointer;
+  color: var(--muted);
+  overflow-wrap: anywhere;
+}
+.tl-agent {
+  margin-top: 0.6rem;
+  display: grid;
+  gap: 0.45rem;
+}
+.tl-agent-ev {
+  display: grid;
+  grid-template-columns: 70px minmax(0, 1fr);
+  gap: 0.25rem 0.8rem;
+  padding-bottom: 0.45rem;
+  border-bottom: 1px dashed var(--line);
+}
+.tl-agent-ev:last-child { border-bottom: 0; }
+.tl-agent-ev .tl-data { grid-column: 2; }
+.tl-poller { margin-top: 0.9rem; font-size: 0.85rem; }
+.lv-debug { color: var(--muted); }
+.tl-ev.lv-warning, .tl-group .lv-warning, .tl-agent-ev.lv-warning { border-left-color: var(--warn); color: var(--warn); }
+.tl-ev.lv-error, .tl-group .lv-error, .tl-agent-ev.lv-error { border-left-color: var(--bad); color: var(--bad); }
+
+@media (max-width: 960px) {
+  .layout-two-col { grid-template-columns: 1fr; }
+  .filters { grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); }
+}
+
+@media (max-width: 720px) {
+  .site-header__inner,
+  .page-shell { padding-left: 1rem; padding-right: 1rem; }
+  .site-header__inner { flex-wrap: wrap; }
+  .user { margin-left: 0; width: 100%; }
+  .card { padding: 1rem; border-radius: 18px; }
+  .kv { grid-template-columns: 1fr; }
+  .tl-ev {
+    grid-template-columns: 70px minmax(0, 1fr);
+  }
+  .tl-kind,
+  .tl-where,
+  .tl-msg,
+  .tl-data {
+    grid-column: 1 / -1;
+  }
+  .data-table { min-width: 560px; }
+}
diff --git a/prsec/dashboard/static/dashboard.js b/prsec/dashboard/static/dashboard.js
new file mode 100644
index 0000000..69eea97
--- /dev/null
+++ b/prsec/dashboard/static/dashboard.js
@@ -0,0 +1,203 @@
+"use strict";
+
+(function () {
+  const PARTIAL_REQUEST = "X-Partial-Request";
+  const PARTIAL_TARGET = "X-Partial-Target";
+  let timelineTimer = null;
+
+  function parseFragment(html) {
+    const template = document.createElement("template");
+    template.innerHTML = html.trim();
+    return template.content;
+  }
+
+  function setRegionContent(target, html) {
+    const fragment = parseFragment(html);
+    target.replaceChildren(fragment);
+  }
+
+  async function fetchText(url, options) {
+    const response = await fetch(url, { credentials: "same-origin", ...options });
+    if (!response.ok) {
+      throw new Error(`Request failed with ${response.status}`);
+    }
+    return response.text();
+  }
+
+  function formUrl(form) {
+    const url = new URL(form.getAttribute("action") || window.location.href, window.location.origin);
+    const data = new FormData(form);
+    url.search = "";
+    for (const [key, value] of data.entries()) {
+      if (typeof value === "string" && value !== "") {
+        url.searchParams.append(key, value);
+      }
+    }
+    return url;
+  }
+
+  function initFilters() {
+    const form = document.querySelector("[data-dashboard-filters]");
+    const targetId = form?.dataset.partialTarget;
+    const target = targetId ? document.getElementById(targetId) : null;
+    if (!form || !target) {
+      return;
+    }
+
+    let requestId = 0;
+    const submit = async () => {
+      const url = formUrl(form);
+      requestId += 1;
+      const currentId = requestId;
+      try {
+        const html = await fetchText(url, {
+          headers: {
+            [PARTIAL_REQUEST]: "true",
+            [PARTIAL_TARGET]: target.id,
+          },
+        });
+        if (currentId !== requestId) {
+          return;
+        }
+        history.replaceState({}, "", `${url.pathname}${url.search}` || "/findings");
+        setRegionContent(target, html);
+      } catch {
+        form.submit();
+      }
+    };
+
+    form.addEventListener("change", (event) => {
+      if (event.target instanceof HTMLInputElement || event.target instanceof HTMLSelectElement) {
+        void submit();
+      }
+    });
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+      void submit();
+    });
+  }
+
+  function initTriage() {
+    const form = document.querySelector("[data-dashboard-triage]");
+    const targetId = form?.dataset.partialTarget;
+    const target = targetId ? document.getElementById(targetId) : null;
+    if (!form || !target) {
+      return;
+    }
+
+    form.addEventListener("submit", async (event) => {
+      event.preventDefault();
+      try {
+        const html = await fetchText(form.action, {
+          method: "POST",
+          headers: {
+            [PARTIAL_REQUEST]: "true",
+            [PARTIAL_TARGET]: target.id,
+          },
+          body: new FormData(form),
+        });
+        setRegionContent(target, html);
+        initTriage();
+      } catch {
+        form.submit();
+      }
+    });
+  }
+
+  function dedupeAppend(target, fragment) {
+    const container = document.createElement("div");
+    container.append(fragment.cloneNode(true));
+    const children = Array.from(container.children).length
+      ? Array.from(container.children)
+      : Array.from(fragment.childNodes).filter((node) => node instanceof Element || node.textContent?.trim());
+
+    for (const node of children) {
+      if (!(node instanceof Element)) {
+        target.append(node.cloneNode(true));
+        continue;
+      }
+      const ids = node.hasAttribute("data-id")
+        ? [node.getAttribute("data-id")]
+        : Array.from(node.querySelectorAll("[data-id]")).map((item) => item.getAttribute("data-id"));
+      if (ids.length && ids.every((id) => id && document.querySelector(`[data-id="${CSS.escape(id)}"]`))) {
+        continue;
+      }
+      target.append(node.cloneNode(true));
+    }
+  }
+
+  function applyTimelineResponse(html) {
+    const fragment = parseFragment(html);
+
+    for (const marker of fragment.querySelectorAll("[data-remove-target]")) {
+      const target = document.querySelector(marker.getAttribute("data-remove-target"));
+      target?.remove();
+    }
+
+    for (const replacement of fragment.querySelectorAll("[data-replace-target]")) {
+      const target = document.querySelector(replacement.getAttribute("data-replace-target"));
+      if (target) {
+        target.replaceWith(replacement.cloneNode(true));
+      }
+    }
+
+    for (const template of fragment.querySelectorAll("template[data-append-target]")) {
+      const target = document.querySelector(template.getAttribute("data-append-target"));
+      if (!target) {
+        continue;
+      }
+      const content = template.content.cloneNode(true);
+      const list = content.firstElementChild;
+      dedupeAppend(target, list && list.tagName === "OL" ? list : content);
+    }
+  }
+
+  async function pollTimeline() {
+    const poller = document.querySelector("[data-dashboard-timeline-poller]");
+    if (!poller || poller.dataset.live !== "true" || !poller.dataset.pollUrl) {
+      return;
+    }
+    try {
+      const html = await fetchText(poller.dataset.pollUrl, {
+        headers: {
+          [PARTIAL_REQUEST]: "true",
+          [PARTIAL_TARGET]: "timeline",
+        },
+      });
+      applyTimelineResponse(html);
+    } catch {
+      // Keep the manual reload fallback visible.
+    } finally {
+      scheduleTimeline();
+    }
+  }
+
+  function scheduleTimeline() {
+    if (timelineTimer !== null) {
+      window.clearTimeout(timelineTimer);
+      timelineTimer = null;
+    }
+    const poller = document.querySelector("[data-dashboard-timeline-poller]");
+    if (!poller || poller.dataset.live !== "true" || !poller.dataset.pollUrl) {
+      return;
+    }
+    const delay = Number.parseInt(poller.dataset.pollInterval || "2000", 10);
+    timelineTimer = window.setTimeout(() => {
+      timelineTimer = null;
+      void pollTimeline();
+    }, Number.isFinite(delay) ? delay : 2000);
+  }
+
+  function init() {
+    initFilters();
+    initTriage();
+    scheduleTimeline();
+  }
+
+  if (document.readyState === "loading") {
+    document.addEventListener("DOMContentLoaded", init, { once: true });
+  } else {
+    init();
+  }
+})();
