+  <div class="page-header">
+    <div>
+      <p class="eyebrow">Dashboard</p>
+      <h1>Scans</h1>
+      <p class="lead">Track pipeline progress, triage decisions, costs, and output links without changing existing scan workflows.</p>
+    </div>
